// The two generated files of the publisher script, built from their sources (run scripts/build-gas.ts):
//   google-workspace/publisher/Page.html  the page readers get: the site's stylesheet, the browser
//                                         app (google-workspace/site/app.js) and a slot for the data
//   google-workspace/publisher/Doc.gs     turns a Google Doc into article HTML: marked (MIT), the
//                                         Doc cleaner (scripts/lib/doc-markdown.ts) and a safe renderer
import { readFileSync } from 'node:fs';
import { stripTypeScriptTypes } from 'node:module';
import { p } from './util.ts';

export function buildGas(): { page: string; doc: string } {

// ---- Page.html -------------------------------------------------------------------------------
const tokens = readFileSync(p('src/styles/tokens.css'), 'utf8');
const global = readFileSync(p('src/styles/global.css'), 'utf8').replace(/^@import[^\n]*\n/gm, '');
const extra = `
/* Only on the Google-hosted site: the search form (the Astro site used Pagefind's). */
.search-form { display: flex; gap: 0.6rem; max-width: 46rem; margin-bottom: 1.6rem; }
.search-form input { flex: 1; min-width: 0; font: 400 1.0625rem var(--font-ui); padding: 0.75rem 0.9rem; border: 1px solid var(--ink-faint); border-radius: 0; background: #fff; color: var(--ink); }
.search-results .archive-row .dek { color: var(--ink-soft); font-size: 0.95rem; }
`;
// Google Fonts names the families without "Variable".
const css = (tokens + global + extra).replace(/'Newsreader Variable'/g, "'Newsreader'").replace(/'Inter Variable'/g, "'Inter'");
const app = readFileSync(p('google-workspace/site/app.js'), 'utf8');
if (/<\/script/i.test(app) || /<\/style/i.test(css)) throw new Error('the app or the stylesheet contains a closing tag');
const page = `<!DOCTYPE html>
<html lang="en">
<head>
<base target="_top">
<meta charset="utf-8">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400..700&family=Newsreader:ital,opsz,wght@0,6..72,400..800;1,6..72,400..800&display=swap">
<style>
${css}
</style>
</head>
<body>
<div id="app"></div>
<script>
${app}
</script>
<script>GovernorApp.start(<?!= boot ?>);</script>
</body>
</html>
`;
const pageFile = '<!-- Generated by scripts/build-gas.ts from google-workspace/site/app.js and src/styles. Do not edit here. -->\n' + page;

// ---- Doc.gs ----------------------------------------------------------------------------------
const marked = readFileSync(p('node_modules/marked/lib/marked.umd.js'), 'utf8').replace(/\n\/\/# sourceMappingURL=.*$/m, '');
const cleaner = stripTypeScriptTypes(readFileSync(p('scripts/lib/doc-markdown.ts'), 'utf8'))
  .replace(/^import [^\n]*\n/gm, '')
  .replace(/^export /gm, '');
const slugify = `function slugify(s) {
  return s.normalize('NFKD').replace(/[\\u0300-\\u036f]/g, '').toLowerCase().replace(/[‘’'\`]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}`;
const doc = `/**
 * The Governor publisher: turning a Google Doc into article HTML.
 * Generated by scripts/build-gas.ts from scripts/lib/doc-markdown.ts and the marked library
 * (https://github.com/markedjs/marked, MIT License). Do not edit here: edit those and rebuild.
 */

${marked}

/** The Doc cleaner from the website's repository (scripts/lib/doc-markdown.ts). */
const DocMarkdown = (function () {
${slugify}
${cleaner}
return { cleanDocMarkdown: cleanDocMarkdown, textToMarkdown: textToMarkdown, imageRefs: imageRefs, makeSafe: makeSafe, splitWriters: splitWriters, parseWriter: parseWriter };
})();

/**
 * Markdown to HTML for articles from the Sheet. HTML typed into a Doc is shown as text, links may
 * only point to web pages, email addresses or this site, and only pictures the publisher copied
 * into Drive (gdrive:<id>) are shown, with sizes for every screen. A picture with a caption on its
 * own line becomes a figure.
 */
const DocRender = (function () {
  const esc = function (s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  const SAFE = /^(https?:\\/\\/|mailto:|\\/(?!\\/)|#)/i;
  function image(token, sizes) {
    const m = /^gdrive:([A-Za-z0-9_-]+)$/.exec(token.href || '');
    if (!m) return '';
    const info = sizes[m[1]] || {};
    const widths = [480, 960, 1600].filter(function (w) { return !info.w || w < info.w; });
    if (info.w && (!widths.length || widths[widths.length - 1] < info.w)) widths.push(Math.min(info.w, 2000));
    const url = function (w) { return 'https://lh3.googleusercontent.com/d/' + m[1] + '=w' + w; };
    return '<img src="' + url(widths[Math.min(1, widths.length - 1)]) + '" srcset="' + widths.map(function (w) { return url(w) + ' ' + w + 'w'; }).join(', ') + '"'
      + ' sizes="(min-width: 800px) 720px, 100vw"' + (info.w ? ' width="' + info.w + '" height="' + info.h + '"' : '') + ' alt="' + esc(token.text) + '" loading="lazy" decoding="async">';
  }
  function render(markdown, sizes) {
    sizes = sizes || {};
    const m = new marked.Marked({ gfm: true, breaks: false, async: false });
    m.use({
      renderer: {
        html: function (token) { return esc(token.text); },
        link: function (token) {
          const inner = this.parser.parseInline(token.tokens);
          if (!SAFE.test(token.href || '')) return inner;
          const outside = /^(https?:|mailto:)/i.test(token.href);
          return '<a href="' + esc(token.href) + '"' + (token.title ? ' title="' + esc(token.title) + '"' : '') + (outside ? ' target="_blank" rel="noopener"' : '') + '>' + inner + '</a>';
        },
        image: function (token) { return image(token, sizes); },
        paragraph: function (token) {
          const only = token.tokens && token.tokens.length === 1 && token.tokens[0].type === 'image' ? token.tokens[0] : null;
          if (only && only.title) return '<figure>' + image(only, sizes) + '<figcaption>' + esc(only.title) + '</figcaption></figure>\\n';
          return '<p>' + this.parser.parseInline(token.tokens) + '</p>\\n';
        },
      },
    });
    return m.parse(markdown);
  }
  return { render: render };
})();
`;
return { page: pageFile, doc: doc };
}
